// aiiot.js
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

import './Aiiot.css';  // Note the capital A

// Feather Icons Replacement Component
const FeatherIcon = ({ name, className = "" }) => {
    return <i data-feather={name} className={className}></i>;
};

// Carousel Images
const CAROUSEL_IMAGES = [
    { src: "/carousel-images/1 (1).jpg", alt: "AI-IoT Innovation Technology" },
    { src: "/carousel-images/1 (4).jpg", alt: "Research Laboratory" },
    { src: "/carousel-images/1 (2).jpg", alt: "Collaborative Technology" }
];

// Project Data
const PROJECT_DATA = [
    { 
        title: "AI Hardware Design", 
        description: "Advanced neural network hardware integration",
        link: "#",
        icon: "trending-up"
    },
    { 
        title: "IoT Connectivity", 
        description: "Next-generation sensor network protocols",
        link: "#", 
        icon: "settings"
    }
];

// Hero Section Component
export const HeroSection = () => {
    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentImageIndex((prevIndex) => 
                (prevIndex + 1) % CAROUSEL_IMAGES.length
            );
        }, 4000);

        return () => clearInterval(interval);
    }, []);

    return (
        <section id="hero" className="aiiot-hero-section relative hero-gradient py-20 md:py-32">
            <div className="aiiot-hero-content max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h1 className="aiiot-hero-title text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight reveal-on-scroll">
                    <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
                    <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                </h1>
                <p className="aiiot-hero-subtitle text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto reveal-on-scroll">
                    The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div className="aiiot-hero-cta flex flex-col sm:flex-row justify-center items-center gap-4 mb-12 reveal-on-scroll">
                    {/* buttons unchanged */}
                </div>

                {/* Hero Image Carousel */}
                <div className="aiiot-hero-carousel relative max-w-5xl mx-auto reveal-on-scroll">
                    {/* ...carousel content... */}
                </div>
            </div>
        </section>
    );
};

// About Section Component
export const AboutSection = () => {
    return (
        <section id="about" className="py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="text-center mb-12 reveal-on-scroll">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">About Our Center</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">
                        Pioneering research where intelligence meets connectivity.
                    </p>
                </div>
                <div className="grid md:grid-cols-2 gap-12 items-center">
                    <div className="reveal-on-scroll">
                        <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                            <img 
                                src="/carousel-images/1 (4).jpg" 
                                alt="Collaborative team working in a modern tech lab" 
                                loading="lazy" 
                                className="w-full h-auto object-cover"
                            />
                        </div>
                    </div>
                    <div className="reveal-on-scroll">
                        <h3 className="text-2xl font-bold text-slate-800 mb-4">
                            Our Mission
                        </h3>
                        <p className="text-slate-600 mb-4">
                            We bridge the gap between advanced electronics, artificial intelligence, and internet of things technologies to create innovative solutions that transform industries.
                        </p>
                        <div className="space-y-3">
                            {PROJECT_DATA.map((project, index) => (
                                <div key={index} className="flex items-start space-x-3">
                                    <FeatherIcon name={project.icon} className="text-blue-600 w-5 h-5" />
                                    <div>
                                        <h4 className="font-semibold text-slate-800">{project.title}</h4>
                                        <p className="text-slate-600 text-sm">{project.description}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

// AI-IoT Innovation Center Page Component
export const AiIotInnovationCenter = () => {
    return (
        <div className="min-h-screen flex flex-col">
            <main className="flex-grow">
                <HeroSection />
                <AboutSection />
                {/* Add more sections as needed */}
            </main>
        </div>
    );
};

export default AiIotInnovationCenter;
